'use strict';
const cities=[['Все направления','all','5 направлений'],['Сочи','sochi','2 курорта'],['Дмитров и Яхрома','moscow','Сорочаны, Волен / Степаново'],['Шерегеш','siberia','1 направление']];
const planned=['Москва','Сергиев Посад','Санкт-Петербург','Кировск','Домбай','Теберда','Архыз','Терскол','Белокуриха','Горно-Алтайск','Миасс','Куса','Красноярск','Южно-Сахалинск','Байкальск'];
let deferredInstall=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
function installHelp(){modal('<span class="eyebrow">ПРИЛОЖЕНИЕ ПОД РУКОЙ</span><h2>На домашний экран.</h2><p><strong>iPhone:</strong> открой эту страницу в Safari, нажми «Поделиться», затем «На экран Домой» и «Добавить».</p><p><strong>Android:</strong> открой страницу в Chrome, выбери «Установить приложение» или «Добавить на главный экран» в меню браузера.</p><p>Откроется отдельное окно без лишних панелей. Установка зависит от браузера. Закрытый доступ через ChatGPT сохраняется. Первый вход требует интернета; автономность закрытого размещения не гарантируется.</p>')}
$('#installapp').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else installHelp()};
$('#choosecity').onclick=()=>{modal('<span class="eyebrow">КУДА ОТПРАВИМСЯ?</span><h2>Выбери направление</h2><input class="citysearch" id="citysearch" placeholder="Город или курорт" aria-label="Поиск города"><div class="citylist" id="citylist"></div><p>В каталоге 5 направлений. Остальные города - план расширения, карточки курортов для них ещё не добавлены.</p>');const draw=()=>{const q=$('#citysearch').value.toLocaleLowerCase();$('#citylist').innerHTML=cities.filter(c=>c[0].toLocaleLowerCase().includes(q)).map(c=>`<button data-city="${c[1]}"><strong>${c[0]}</strong><span>${c[2]}</span></button>`).join('')+planned.filter(c=>c.toLocaleLowerCase().includes(q)).map(c=>`<div class="plannedcity">${c}<small>В плане каталога</small></div>`).join('');$$('[data-city]').forEach(b=>b.onclick=()=>{filter=b.dataset.city;$('#citylabel').textContent=cities.find(c=>c[1]===filter)[0];$$('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));renderCards();$('#modal').close()})};$('#citysearch').oninput=draw;draw()};
$('#open-settings').onclick=settings;
function settings(){modal('<span class="eyebrow">ПРОСТРАНСТВО КАВЫ</span><h2>Всё под контролем.</h2><div class="settingslist"><button id="installsetting">Установить на домашний экран ↗</button><a href="privacy.html">Конфиденциальность ↗</a><a href="storage.html">Данные, cookies и хранение ↗</a><a href="terms.html">Условия использования ↗</a><button id="clear-data" class="danger">Удалить мои данные с устройства</button></div><p>Версия 0.5 · Мобильный прототип. Реальная геолокация и платежи не подключены.</p>');$('#installsetting').onclick=installHelp;$('#clear-data').onclick=()=>{modal('<h2>Удалить локальные данные?</h2><p>Будут удалены демо-заезды, избранное и сохранённые демо-пакеты этого приложения. Это действие нельзя отменить. Куки входа ChatGPT не затрагиваются.</p><button class="primary" id="confirmclear">Удалить данные приложения</button><button class="outline full" id="cancelclear">Оставить данные</button>');$('#cancelclear').onclick=settings;$('#confirmclear').onclick=()=>{['snow-history','snow-favorites','snow-packages'].forEach(k=>localStorage.removeItem(k));history=[];favorites=[];downloaded=[];renderCards();renderHistory();updatePackage();$('#modal').close();toast('Локальные данные удалены')}}}
// Do not cache authenticated HTML, user data or the access gateway. Only public static assets.
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.addEventListener('offline',()=>toast('Связь потеряна. Открытое демо продолжает работать.'));
const mountainElement=$('#mountain');mountainElement.tabIndex=0;mountainElement.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();rotation+=e.key==='ArrowLeft'?-.12:.12;scheduleMountain()}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$('#citylabel').textContent=cities.find(c=>c[1]===b.dataset.filter)?.[0]||'Все направления'}));
